Script B — ChatGPT DOM Probe

For: Prompt 7 (ChatGPT Scraper)
Run on: chatgpt.com — open a conversation with at least 4 messages. Run ONCE.

javascript

```javascript
(function chatgptDOMProbe() {
  console.log('\n========== CONTEXTMOVER: CHATGPT DOM PROBE ==========\n');

  // ── SECTION 1: data-message-author-role scan (ChatGPT's stable attribute) ──
  const authorRoleEls = document.querySelectorAll('[data-message-author-role]');
  console.log(`[data-message-author-role] elements found: ${authorRoleEls.length}`);
  if (authorRoleEls.length > 0) {
    const roles = [...new Set([...authorRoleEls].map(el => el.dataset.messageAuthorRole))];
    console.log('  Role values present:', roles.join(', '));
    roles.forEach(role => {
      const matching = [...authorRoleEls].filter(el => el.dataset.messageAuthorRole === role);
      const el = matching[0];
      console.log(`\n  role="${role}" → ${matching.length} elements`);
      console.log(`    tag: ${el.tagName}, classes: ${el.className?.toString().slice(0,100)}`);
      console.log(`    text: "${el.textContent.trim().replace(/\s+/g,' ').slice(0,100)}"`);
    });
  }

  // ── SECTION 2: data-testid scan ────────────────────────────────────────────
  const testIds = [...new Set(
    [...document.querySelectorAll('[data-testid]')].map(el => el.dataset.testid)
  )].filter(t => /message|turn|conv|user|assistant|human|chat/i.test(t)).sort();
  console.log('\nRELEVANT data-testid VALUES:\n' + (testIds.join('\n') || '(none found)'));

  // ── SECTION 3: Test selector patterns ─────────────────────────────────────
  const candidates = [
    '[data-message-author-role="user"]',
    '[data-message-author-role="assistant"]',
    '[data-testid^="conversation-turn"]',
    '[data-testid="user-message"]',
    '[data-testid="assistant-message"]',
    '[class*="message-content"]',
    '[class*="MessageContent"]',
    '[class*="ConversationItem"]',
    '[class*="group/conversation"]',
    '[class*="agent-turn"]',
    '[class*="text-message"]',
    'article',
    '[role="article"]',
  ];

  console.log('\nSELECTOR TEST RESULTS:');
  candidates.forEach(sel => {
    try {
      const els = [...document.querySelectorAll(sel)];
      if (els.length > 0) {
        console.log(`\n  ✅ "${sel}" → ${els.length} elements`);
        els.slice(0, 2).forEach((el, i) => {
          const text = el.textContent.trim().replace(/\s+/g,' ').slice(0,100);
          const dataAttrs = [...el.attributes].filter(a => /^data-/.test(a.name)).map(a=>`${a.name}="${a.value}"`).join(', ');
          console.log(`     [${i}] ${el.tagName} | data: ${dataAttrs || 'none'} | text: "${text}"`);
        });
      }
    } catch(e) {}
  });

  // ── SECTION 4: Virtual scroll container ───────────────────────────────────
  console.log('\nVIRTUAL SCROLL / THREAD CONTAINER:');
  ['#thread-messages', '[class*="thread"]', '[class*="overflow-y-auto"]',
   'main', '[role="main"]', '[class*="ChatLayout"]', '[class*="conversation-container"]',
   '[class*="react-scroll"]', '[data-testid="conversation"]'].forEach(sel => {
    const el = document.querySelector(sel);
    if (el) {
      const style = window.getComputedStyle(el);
      console.log(`  "${sel}" → overflow-y: ${style.overflowY}, height: ${style.height}, children: ${el.children.length}`);
    }
  });

  // ── SECTION 5: Message count check ────────────────────────────────────────
  console.log('\nMESSAGE COUNT SANITY CHECK:');
  const totalMsgs = document.querySelectorAll('[data-message-author-role]').length;
  const visibleMsgs = [...document.querySelectorAll('[data-message-author-role]')]
    .filter(el => el.getBoundingClientRect().height > 0).length;
  console.log(`  Total [data-message-author-role] in DOM: ${totalMsgs}`);
  console.log(`  Visible (non-zero height): ${visibleMsgs}`);
  console.log(`  → If visibleMsgs << totalMsgs, virtual scroll is hiding elements`);

  console.log('\n========== END CHATGPT DOM PROBE ==========\n');
})();
```

