Script G — Gemini Input Field Probe

For: Prompt 12 (Gemini Injection)
Run on: gemini.google.com — on any conversation page (the input box must be visible)
Note: This is separate from Script C. Script C is for the scraper selectors. This one is specifically for finding the input field structure.

javascript

```javascript
(function geminiInputProbe() {
  console.log('\n========== CONTEXTMOVER: GEMINI INPUT FIELD PROBE ==========\n');

  // ── SECTION 1: Find all input-like elements ────────────────────────────────
  console.log('ALL INPUT-LIKE ELEMENTS:');
  const inputSelectors = [
    'textarea',
    'input[type="text"]',
    '[contenteditable="true"]',
    '[contenteditable]',
    '[role="textbox"]',
    'rich-textarea',
    '[class*="input"]', '[class*="Input"]',
    '[class*="textarea"]', '[class*="Textarea"]',
    '[class*="prompt"]', '[class*="Prompt"]',
    '[class*="composer"]', '[class*="Composer"]',
    '[class*="query-input"]', '[class*="chat-input"]',
  ];

  inputSelectors.forEach(sel => {
    try {
      const els = [...document.querySelectorAll(sel)];
      if (els.length > 0) {
        els.forEach((el, i) => {
          const rect = el.getBoundingClientRect();
          const isVisible = rect.height > 0 && rect.width > 0;
          const dataAttrs = [...el.attributes].map(a=>`${a.name}="${a.value.slice(0,40)}"`).join(' ');
          console.log(`\n  ✅ "${sel}" [${i}] — visible: ${isVisible}`);
          console.log(`     tag: <${el.tagName.toLowerCase()}>`);
          console.log(`     attrs: ${dataAttrs.slice(0,200)}`);
          console.log(`     class: ${el.className?.toString().slice(0,100)}`);
          console.log(`     value/textContent: "${(el.value || el.textContent || '').trim().slice(0,60)}"`);
          console.log(`     hasShadowRoot: ${!!el.shadowRoot}`);
          if (el.shadowRoot) {
            const shadowInputs = el.shadowRoot.querySelectorAll('textarea, [contenteditable], input');
            console.log(`     shadowRoot inputs: ${shadowInputs.length}`);
            shadowInputs.forEach((si,j) => {
              console.log(`       shadow[${j}] <${si.tagName.toLowerCase()}> class="${si.className?.toString().slice(0,60)}"`);
            });
          }
        });
      }
    } catch(e) {}
  });

  // ── SECTION 2: Submit button ───────────────────────────────────────────────
  console.log('\n\nSUBMIT BUTTON:');
  ['button[aria-label*="send" i]', 'button[aria-label*="submit" i]',
   '[data-testid*="send"]', '[class*="send-button"]', '[class*="SendButton"]',
   'button[type="submit"]', '[class*="submit"]',
   'rich-textarea + button', '[class*="send"]'].forEach(sel => {
    const el = document.querySelector(sel);
    if (el) {
      console.log(`  "${sel}" → <${el.tagName.toLowerCase()}> aria-label="${el.getAttribute('aria-label')}" disabled=${el.disabled} class="${el.className?.toString().slice(0,60)}"`);
    }
  });

  // ── SECTION 3: Detect framework ───────────────────────────────────────────
  console.log('\nFRAMEWORK DETECTION:');
  const isAngular = !!document.querySelector('[ng-version], [_nghost], [ng-reflect]') || !!window.ng;
  const isReact = !!(document.querySelector('[data-reactroot]') || window.__REACT_DEVTOOLS_GLOBAL_HOOK__);
  const hasAngularCustomElements = !!document.querySelector('rich-textarea, model-response');
  console.log(`  Angular detected: ${isAngular}`);
  console.log(`  React detected: ${isReact}`);
  console.log(`  Angular custom elements present: ${hasAngularCustomElements}`);

  // ── SECTION 4: Try to set a test value (non-destructive) ─────────────────
  console.log('\nINJECTION METHOD TEST (non-destructive — will not change visible content):');
  const textarea = document.querySelector('textarea');
  const richTextarea = document.querySelector('rich-textarea');
  const contentEditable = document.querySelector('[contenteditable="true"]');

  if (textarea) {
    const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value')?.set;
    console.log(`  textarea found — nativeInputValueSetter available: ${!!nativeInputValueSetter}`);
    console.log(`  Use: nativeInputValueSetter.call(el, text); el.dispatchEvent(new Event('input', {bubbles:true}))`);
  }
  if (richTextarea) {
    console.log(`  <rich-textarea> found — check shadowRoot for inner textarea`);
    const inner = richTextarea.shadowRoot?.querySelector('textarea, [contenteditable]');
    console.log(`  Inner element in shadowRoot: ${inner ? inner.tagName : 'NOT FOUND'}`);
  }
  if (contentEditable) {
    console.log(`  [contenteditable] found — use: el.textContent = text; el.dispatchEvent(new InputEvent('input', {bubbles:true, data:text}))`);
  }

  console.log('\n========== END GEMINI INPUT FIELD PROBE ==========\n');
})();
```

